    [2204] = "Besorgt Euch eine Kraftquelle vom mächtigsten Konstrukt, das Ihr in Uldaman finden könnt, und liefert sie bei Talvash del Kissel in Ironforge ab.",
    [2240] = "Lest Baelogs Tagebuch, erforscht die geheime Kammer und erstattet dann Ausgrabungsleiter Stormpike Bericht.",
    [2278] = "Sprecht mit dem Steinbehüter und findet heraus, welche uralten Lehren er aufbewahrt. Sobald Ihr alles erfahren habt, was er weiß, aktiviert die Scheiben von Norgannon.",
    [2279] = "Bringt die Miniaturausgabe der Scheiben von Norgannon zur Forscherliga nach Ironforge.",
    [2280] = "Bringt die Miniaturausgabe der Scheiben von Norgannon zu einem der Weisen von Thunder Bluff.",
    [2283] = "Sucht in der Grabungsstätte von Uldaman nach einer wertvollen Halskette und bringt sie nach Orgrimmar zu Dran Droffers. Die Halskette ist vielleicht beschädigt.",
    [2284] = "Sucht in den Tiefen von Uldaman nach einem Hinweis auf den Verbleib der Edelsteine.",
    [2318] = "Sucht jemanden, der das Tagebuch des Paladins übersetzen kann. Der nächstgelegene Ort, wo Ihr so jemanden finden könntet, ist Kargath im Ödland.",
    [2338] = "Leiht Jarkal die Halskette. Im Gegenzug wird er das Tagebuch für Euch übersetzen.",
    [2339] = "Beschafft in Uldaman alle drei Edelsteine sowie eine Kraftquelle für die Halskette und bringt sie anschließend zu Jarkal Mossmeld nach Kargath. Jarkal glaubt, dass sich eine Kraftquelle vielleicht im stärksten Konstrukt in Uldaman findet.$B$BAus dem Tagebuch, wisst Ihr...$B* Der Rubin wurde in einer Bastion der Zwerge der Schattenschmiede versteckt.$B* Der Topas steckt in einer Urne in einem der Trogg-Gebiete, in der Nähe einiger Zwerge der Allianz.$B* Der Saphir wurde von Grimlok, dem Anführer der Troggs, mitgenommen.",
    [2340] = "Liefert die Halskette und die geborgenen Edelsteine bei Dran Droffers in Orgrimmar ab.",
    [2341] = "Besucht Jarkal Mossmeld in Kargath, um festzustellen, ob er Erfolg gehabt hat.",
    [2342] = "Holt Patrick Garretts Familienschatz aus der Truhe der Familie in der südlichen Bankenhalle von Uldaman und bringt diesen zu ihm nach Undercity.",
    [2359] = "Stehlt den Turmschlüssel der Defias, brecht in den Turm der Defias ein und stellt fest, was sich in der Dämmerwaldtruhe befindet. Bringt Mathias Shaw in Stormwind dann alle Informationen über das, was Ihr herausgefunden habt. Lest Kearnens Tagebuch, um neue Erkenntnisse über den Turm zu erlangen.",
    [2360] = "Reist nach Westfall und sucht Agentin Kearnen. Sie wird Euch Bericht erstatten.",
    [2361] = "Ich gebe Euch diese Halskette gern, $C. Ihr habt mir einen unschätzbaren Dienst erwiesen und dafür danke ich Euch. Tragt die Kette mit Stolz und vergesst nicht, immer wieder in der gebührenden Lautstärke zu verkünden, wer sie für Euch gemacht hat!$B$BUnd wenn Ihr auch beiläufig erwähnen könntet, dass die Kette nicht verflucht ist, dann wäre das wirklich wunderbar.",
    [2398] = "Sucht in Uldaman nach Baelog.",
    [2418] = "Bringt Rigglefuzz im Ödland 8 Kraftsteine aus Dentrium und 8 Kraftsteine aus An'Alleum.",
    [2439] = "Bringt Euren Belohnungsgutschein zu Dinita Stonemantle im Gewölbe von Ironforge.",
    [2440] = "Bringt den Belohnungsgutschein zu Bena Winterhoof nach Thunder Bluff.",
    [2458] = "Reist zum Turm der Venture Company nördlich des Schlickermoores und kontaktiert dort den Agenten der Shattered-Hand, Zuchtmeister Fizzule.$B$BSobald der Turm in Sichtweite ist, verwendet die Leuchtfeuerwaffe, um Zuchtmeister Fizzule Eure Ankunft anzuzeigen. Feuert ZWEI Leuchtfeuergeschosse ab, nähert Euch dann Zuchtmeister Fizzule und zeigt den Gruß der Shattered-Hand.$B$BEs ist wichtig, dass Ihr diese Aktionen in der richtigen Reihenfolge durchführt, da Fizzule jede Person, die er nicht erkennt, angreift und eliminiert.",
    [2460] = "Führt Shenthul gegenüber den Shattered-Gruß aus.",
    [2478] = "Stehlt Silixiz' Turmschlüssel von Großknecht Silixiz. Tötet dann 2 mutierte Drohnen der Venture Co., 2 Patrouillen der Venture Co. und 2 Ausgucker der Venture Co.$B$BEliminiert den obersten Großknecht Gallywix und nehmt seinen Kopf. Knackt dann das Schloss von Gallywix' Schließkassette und stehlt den Vorrat an Zanzils veränderter Mixtur. Bringt den Vorrat und Gallywix' Kopf zu Shentul nach Orgrimmar; er wird Euch weitere Anweisungen geben.",
    [2479] = "Reist nach Tarrens Mühle im Vorgebirge von Hillsbrad und liefert die Probe von Zanzils Mixtur bei Serge Hinott ab.$B$BUm nach Tarrens Mühle zu kommen, müsst Ihr den Zeppelin nach Undercity nehmen und dann auf der Straße nach Süden durch den Silberwald in Richtung Hillsbrad reisen. Folgt den Schildern!",
    [2480] = "Wartet auf Serge Hinott, um das Heilmittel fertig zu stellen.",
    [2607] = "Sprecht im Keller der Kaserne mit Doc Mixilpixil.",
    [2608] = "Ihr solltet Euch /hinlegen, damit Doc Mixilpixil Euch untersuchen kann. Denn wie soll er ein Heilmittel finden, wenn er die Ursache nicht finden kann?",
    [2609] = "Bringt Doc Mixilpixil 1 Bündel einfache Wildblumen, 1 verbleite Phiole, 1 Bronzeröhre und 1 Rolle blassgelben Seidenfaden. So eine 'Itis' heilt sich nicht von selbst, $Gjunger Herr:junge Dame;.",
    [2621] = "Sprecht in Stonard mit Zentralen-Kommandant Ruag.",
    [2622] = "Sprecht mit Bengor.",
    [2623] = "Beschafft die Befehle des Kriegshäuptlings wieder und gebt sie dem gefallenen Helden der Horde zurück.",
    [2681] = "Befreit 9 Diener von Razelikh, 3 Diener von Sevine, 3 Diener von Allistarj und 3 Diener von Grol. Kehrt zum gefallenen Helden zurück, sobald Ihr die Aufgabe erfüllt habt. Ihr müsst nahe bei den Steinen bleiben, sonst habt Ihr keinen Erfolg.",
    [2701] = "Öffnet die Truhe und nehmt Euch Eure Belohnung.",
    [2702] = "Sprecht mit Corporal Thund Splithoof.",
    [2721] = "Findet heraus, was aus Lieutenant Kirith geworden ist.",
    [2743] = "Kehrt mit Euren neuen Erkenntnissen zum gefallenen Helden der Horde zurück.",
    [2744] = "Sprecht mit Loramus Thalipedes in Azshara.",
    [2745] = "Sprecht in Schloss Stormwind mit Tyrion.",
    [2746] = "Bringt 3 Stück Seidenstoff und 2 frische Äpfel von Clara nach Stormwind zu Tyrion.",
    [2768] = "Bringt die Wünschel-mato-Rute nach Gadgetzan zu Chefingenieur Bilgewhizzle.",
    [2770] = "Bringt Wizzle Brassbolts in der schimmernden Ebene Gahz'rillas energiegeladene Schuppe.",
    [2783] = "Sprecht mit dem gefallenen Helden der Horde im Grenzgebiet zwischen den verwüsteten Landen und dem Sumpf.",
    [2784] = "Lauscht der Geschichte des gefallenen Helden der Horde.",
    [2801] = "Lauscht der Geschichte des gefallenen Helden der Horde.",
    [2846] = "Bringt die Tiara der Tiefen zu Tabetha in den Marschen von Dustwallow.",
    [2861] = "Sprecht mit Tabetha in den Marschen von Dustwallow.",
    [2864] = "Sprecht mit Tran’rek in Gadgetzan.",
    [2865] = "Bringt Tran’rek in Gadgetzan 5 unbeschädigte Skarabäuspanzerschalen.",
    [2936] = "Lest von der Schrifttafel des Theka, um den Namen des Spinnengottes der Witherbark zu erfahren, und kehrt dann zu Meister Gadrin zurück.",
    [2983] = "Sucht Kranal Fiss im Brachland.",
    [2984] = "Sucht Kranal Fiss im Brachland.",
    [2985] = "Sucht Islen Waterseer im Brachland.",
    [2986] = "Sucht Islen Waterseer im Brachland.",
    [2991] = "Bringt Thadius Grimshade in den verwüsteten Landen Nekrums Medaillon.",
    [3001] = "Findet Strahad Farsan in Ratchet.",
    [3042] = "Bringt 20 Phiolen Trollaushärter zu Trenton Lighthammer in Gadgetzan.",
    [3141] = "Lasst Loramus Thalipedes seine Geschichte erzählen.",
    [3369] = "Bringt den Alptraum-Splitter zu Hamuul Runtetotem auf der Anhöhe der Ältesten.",
    [3370] = "Bringt den Alptraum-Splitter zu Mathrengyl Bearwalker in Darnassus.",
    [3373] = "Legt die Essenz von Eranikus in den Essenzborn, der sich in dem Versunkenen Tempel in seinem Unterschlupf befindet.",
    [3380] = "Sucht Marvon Rivetseeker in Tanaris.",
    [3446] = "Sucht den Altar von Hakkar im Versunkenen Tempel in den Sümpfen des Elends.",
    [3447] = "Reist zum Versunkenen Tempel und enthüllt das Geheimnis, das sich in dem Kreis der Statuen verbirgt.",
    [3504] = "Bringt den versiegelten Brief zu Ag'tor Bloodfist nach Azshara.",
    [3505] = "Tötet 6 Blutelfenwiederbeschaffer und 6 Blutelfenfeldmesser, bevor Ihr Euch aufmacht, Rimtoris Quelle der Macht zu finden.",
    [3508] = "Wartet, bis Loramus den Erleuchtungszauber vollendet hat.",
    [3509] = "Sprecht mit Lord Arkkoroc in Azshara. Beginnt Eure Suche am Rand des Wassers, um den Tempel von Arkkoran zu finden.",
    [3510] = "Erschlagt Hetäre und bringt den blutigen Hetärenkopf, den geschlagenen Hetärenkopf und den verwundeten Hetärenkopf zu Lord Arkkoroc.",
    [3511] = "Bringt den Härter zurück zu Loramus Thalipedes.",
    [3520] = "Fangt die Geister von 3 Kreischern in Feralas ein und kehrt dann zu Yeh'kinya in Steamwheedle zurück.",
    [3527] = "Bringt die erste und die zweite Mosh'aru-Schrifttafel zu Yeh'kinya nach Tanaris.",
    [3528] = "Bringt das gefüllte Ei von Hakkar zu Yeh'kinya nach Tanaris.",
    [3602] = "Sammelt 20 kristallisierte Azsharite im südlichen Azshara. Ihr könnt den Teufelshund benutzen, damit er Euch beim 'Erschnüffeln' der gut versteckten Ablagerungen behilflich ist.$B$BKehrt zu Loramus zurück, sobald Ihr die Aufgabe erfüllt habt.",
    [3621] = "Bringt die Lieferung zu Galvan dem Alten im Schlingendorntal.",
    [3625] = "Wartet, bis Galvan die Waffen fertig geschmiedet hat.",
    [3626] = "Kehrt zum Gefallenen Helden der Horde zurück.",
    [3627] = "Tötet Grol den Zerstörer, Lady Sevine und Erzmagier Allistarj. Nehmt das Amulett von Grol, das Amulett von Sevine und das Amulett von Allistarj von ihren Leichen.$B$BDenkt daran, Eure Verzauberte Azsharit-Teufelswaffe zu BENUTZEN, um die Triade zu schwächen. Auf eine andere Weise können sie nicht getötet werden - aber verwendet sie weise ...",
    [3628] = "Vernichtet Razelikh den Entweiher und bringt das abgespaltene Horn des Entweihers zum Gefallenen Helden der Horde. Ihr müsst außerdem den Zauberschutz des Entweihers mit zurückbringen, damit der Gefallene Held ihn zerstören und somit verhindern kann, dass er jemals in die falschen Hände fällt.",
    [3631] = "Sprecht mit Strahad Farsan im Brachland.",
    [3701] = "Begebt Euch zu den Ruinen von Thaurissan in der brennenden Steppe und sammelt Informationen über die Thaurissan-Relikte. Kehrt zur königlichen Historikerin Archesonus zurück, wenn Ihr die Informationen besorgt habt.",
    [3702] = "Hört die Erzählung der königlichen Historikerin Archesonus über die Geschichte von Thaurissan.",
    [3783] = "Sammelt 10 dicke Yetifelle für Umi Rumplesnicker in Everlook.",
    [3801] = "Sprecht mit Franclorn Forgewright, wenn Ihr daran interessiert seid, einen Schlüssel für die Hauptstadt zu erhalten.",
    [3802] = "Erschlagt Fineous Darkvire und bergt den großen Hammer Ironfel. Bringt Ironfel zum Schrein von Thaurissan und legt ihn auf die Statue von Franclorn Forgewright.",
    [3844] = "Sucht in dem Tümpel nach einem Hinweis darauf, wem dieses havarierte Floß gehören könnte.",
    [3845] = "Untersucht die Gegenstände in dem Bündel und bringt sie zu ihrem Besitzer.",
    [3903] = "Sprecht mit Milly Osworth.",
    [3904] = "Bringt 8 Kisten mit Millys Ernte zu Milly Osworth in der Nähe der Abtei von Nordhain.",
    [3907] = "Betretet die Blackrocktiefen und spürt Lord Incendius auf. Tötet ihn und bringt jegliche Informationsquelle, die Ihr finden könnt, zu Thunderheart.",
    [3908] = "Bringt Linkens Schwert zu Donova Snowden in Winterspring.",
    [3909] = "Sucht nach Gregan Brewspewer im nördlichen Feralas. Lasst Euch von ihm erklären, wie Ihr Euch das Videre-Elixier beschaffen könnt, und kehrt dann zu Donova Snowden nach Winterspring zurück.",
    [3912] = "Geht zum Friedhof außerhalb von Gadgetzan und benutzt dort das Videre-Elixier. Befolgt Donovas übrige Anweisungen, um Gaeriyan zu finden.",
    [3913] = "Wenn Ihr auferstanden seid, sucht nach dem Grabstein, von dem Gaeriyan Euch erzählt hat.",
    [3914] = "Liefert Linkens überragendes Schwert bei Linken im Un'Goro Krater ab.",
    [3941] = "Sucht J.D. Collie in der Höhle in Marshals Zuflucht auf.",
    [3942] = "Sucht Eridan Bluewind im südlichen Teil des Teufelswalds.",
    [3961] = "Bringt das Silbertotem von Aquementas zu Linken in Marshals Zuflucht.",
    [3962] = "Begebt Euch zum Feuerfedergrat südlich von Marshals Zuflucht.$B$BSucht Sturmflamme und verwendet das Totem, um die schützende Aura, die ihn umgibt, zu entfernen. Sobald er besiegt ist, holt die Goldene Flamme aus der Höhle.",
    [3981] = "Sucht Kommandant Gor'shak in den Blackrocktiefen.$B$BIhr erinnert Euch, dass auf dem primitiv gezeichneten Bild des Orcs auch Gitter vor dem Gesicht zu sehen waren. Vielleicht solltet Ihr nach einer Art Gefängnis suchen.",
    [3982] = "Verteidigt Gor'shak.",
    [4001] = "Sprecht mit Kharan Mighthammer und sammelt Informationen über die Entführung von Prinzessin Moira Bronzebeard. Bringt diese Informationen dann zu Thrall nach Orgrimmar.$B$BIhr erinnert Euch, dass Gor'shak gesagt hat, Kharan werde in einer Zelle in seiner Nähe festgehalten.",
    [4002] = "Sprecht mit Thrall, wenn Ihr bereit seid, die von ihm geplante Mission zu übernehmen.",
    [4003] = "Tötet Imperator Dagran Thaurissan und befreit Prinzessin Moira Bronzebeard von seinem bösen Zauber.",
    [4004] = "Kehrt zu Thrall zurück!",
    [4005] = "Bringt das Buch von Aquor, die silbrigen Klauen und das Eisenstammherz nach Tanaris.$B$BBenutzt das Buch von Aquor, um Aquementas zu beschwören.$B$BWenn Ihr das vollständige Totem habt, bringt es zu J.D. Collie in Marshals Zuflucht zurück.",
    [4024] = "Begebt Euch in die Blackrocktiefen und tötet Bael'Gar.$B$BIhr wisst lediglich, dass der Riese irgendwo in den Blackrocktiefen haust. Vergesst nicht, die veränderte Haut des schwarzen Drachenschwarms mit Bael'Gars Überresten zu benutzen und damit die feurige Essenz einzufangen.$B$BBringt die eingeschlossene feurige Essenz zu Cyrus Therepentous zurück.",
    [4063] = "Sucht und tötet Golemlord Argelmach. Bringt Lotwil seinen Kopf. Außerdem müsst Ihr 10 intakte Elementarkerne von den Wuthäschergolems und Kriegshetzerkonstrukten, die Argelmach beschützen, beschaffen. Das wisst Ihr, weil Ihr übernatürliche Fähigkeiten habt.",
    [4081] = "Begebt Euch in die Blackrocktiefen und vernichtet die üblen Aggressoren!$B$BKriegsherr Goretooth möchte, dass Ihr 15 Gardisten der Zorneshämmer, 10 Aufseher der Zorneshämmer und 5 Fußsoldaten der Zorneshämmer tötet. Kehrt zu ihm zurück, sobald Ihr die Aufgabe erfüllt habt.",
    [4082] = "Begebt Euch in die Blackrocktiefen und vernichtet die üblen Aggressoren!$B$BKriegsherr Goretooth möchte, dass Ihr 10 Sanitäter der Zorneshämmer, 10 Soldaten der Zorneshämmer und 10 Offiziere der Zorneshämmer tötet. Kehrt zu ihm zurück, sobald Ihr die Aufgabe erfüllt habt.",
    [4083] = "Der spektrale Kelch schwebt in der Luft, leicht ansteigend und dann absinkend, so, als bewege er sich im Takt eines sterbenden Herzens.",
    [4084] = "Beschafft 11 silbrige Klauen und 1 Eisenstammherz für Eridan Bluewind im Teufelswald.",
    [4121] = "Eskortiert Euren Gefangenen, Grark Lorkrub, durch die brennende Steppe und durch den Blackrock in die sengende Schlucht.$B$BEuch fällt ein, dass Lexlort gesagt hat, seine Männer würden auf der anderen Seite warten, um Grark in Gewahrsam zu nehmen.$B$BIhr werdet außerdem Eure Thoriumfesseln an Lexlort übergeben müssen.",
    [4122] = "Begebt Euch in die brennende Steppe und sucht Grark Lorkrub. Ihr erinnert Euch, dass Lexlort gesagt hat, er sei zuletzt in einer großen Festung der Blackrock gesehen worden.$B$BWenn Ihr Grark Lorkrub gefunden habt, verwendet die Thoriumfesseln, um ihn zu binden, und bringt ihn dann über den Blackrock in die sengende Schlucht zurück. Lexlorts Männer werden auf der anderen Seite warten, um Grark in Gewahrsam zu nehmen.",
    [4123] = "Bringt das 'Herz des Berges' zu Maxwort Uberglint in der brennenden Steppe.",
    [4124] = "Sprecht mit Ginro Hearthkindle in der Festung Feathermoon.",
    [4125] = "Sucht das Boot des Kuriers irgendwo entlang der Küste von Feralas.",
    [4126] = "Bringt Ragnar Donnerbräu in Kharanos das gestohlene Donnerbräurezept.",
    [4127] = "Kehrt zur Festung Feathermoon zurück und zeigt Ginro Hearthkindle das gefundene Messer.",
    [4128] = "Sprecht mit Ragnar Donnerbräu.",
    [4129] = "Bringt Quintis Jonespyre in der Festung Feathermoon das gefundene Messer.",
    [4130] = "Sprecht mit Ginro Hearthkindle in der Festung Feathermoon.",
    [4131] = "Durchsucht die Lager der Waldpfotengnolle im Süden Feralas nach Hinweisen auf den Verbleib des Kuriers oder seiner Habseligkeiten.",
    [4132] = "Begebt Euch zu den Blackrocktiefen und eliminiert General Zornesschmied! Kehrt zum Kriegsherrn Goretooth zurück, sobald Ihr diese Aufgabe erledigt habt.",
    [4133] = "Sprecht mit Schattenmeisterin Vivian Lagrave in Kargath.",
    [4134] = "Bringt Vivian Lagrave in Kargath das gestohlene Donnerbräurezept.",
    [4135] = "Da Ihr jetzt Raschals letzten bekannten Aufenthaltsort in Erfahrung gebracht habt, setzt Ihr die Suche nach ihm oder seinen sterblichen Überresten in der verwundenen Tiefe fort. Laut Notiz soll dieser Ort südlich der Lager der Waldpfotengnolle liegen.",
    [4136] = "Bringt Yuka Screwspigot in der brennenden Steppe Ribblys Kopf.",
    [4182] = "Erschlagt 15 schwarze Brutlinge, 10 Exemplare der schwarzen Großdrachenbrut, 4 schwarze Wyrmkin und 1 Schwarzdrachen. Kehrt zu Helendis Riverhorn zurück, sobald die Aufgabe erledigt ist.",
    [4183] = "Reist nach Seenhain und händigt Magistrat Solomon Helendis Riverhorns Brief aus.",
    [4184] = "Reist nach Stormwind und tragt Solomons Hilfegesuch dem Hochlord Bolvar Fordragon vor.$B$BBolvar residiert in der Burg Stormwind.",
    [4185] = "Sprecht zuerst mit Lady Katrana Prestor, dann mit Hochlord Bolvar Fordragon.",
    [4186] = "Händigt Bolvars Erlass an Magistrat Solomon in Seenhain aus.",
    [4201] = "Bringt 4 Gromsblut-Kräuter, 10 Riesensilbervenen und Nagmaras gefüllte Phiole zu Herrin Nagmara in den Blackrocktiefen.",
    [4223] = "Sprecht mit Marshal Maxwell in der brennenden Steppe.",
    [4224] = "Sprecht mit dem struppigen John, um etwas über Marshal Windsors Schicksal zu erfahren, und kehrt dann zu Marshal Maxwell zurück, wenn Ihr diese Aufgabe erledigt habt.$B$BIhr erinnert Euch daran, dass Marshal Maxwell Euch geraten hat, ihn in einer Höhle im Norden zu suchen.",
    [4241] = "Reist zum Blackrock im Nordwesten und dann weiter zu den Blackrocktiefen. Findet heraus, was aus Marshal Windsor geworden ist.$B$BIhr erinnert Euch daran, dass der struppige John sagte, man hätte Windsor in ein Gefängnis verschleppt.",
    [4242] = "Überbringt Marshal Maxwell die schlechten Neuigkeiten.",
    [4263] = "Sucht Lord Incendius in den Blackrocktiefen und vernichtet ihn!",
    [4264] = "Soeben seid Ihr auf etwas gestoßen, das Marshal Windsor mit Sicherheit sehr interessiert. Vielleicht besteht ja doch noch Hoffnung.",
    [4265] = "Begleitet Raschal sicher aus dem Schwarmbau der Zukk'ash hinaus.$B$BKehrt zu Ginro Hearthkindle in der Festung Feathermoon zurück und lasst ihn wissen, dass Raschal am Leben ist und dass es ihm gut geht.",
    [4266] = "Sprecht mit Shandris Feathermoon in der Festung Feathermoon.",
    [4267] = "Bringt Raschals Bericht zu Gracina Spiritmight in Darnassus.",
    [4281] = "Bringt das nicht ausgelieferte Paket zu Falfindel Waywarder in Thalanaar.",
    [4282] = "Holt Marshal Windsors verloren gegangene Informationen zurück.$B$BMarshal Windsor glaubt, dass sich die Informationen in den Händen des Golemlords Argelmach und des Generals Zornesschmied befinden.",
    [4286] = "Reist in die Blackrocktiefen und holt 20 Dunkeleisengürteltaschen. Kehrt zu Oralius zurück, sobald die Aufgabe erledigt ist. Ihr nehmt an, dass die Dunkeleisenzwerge in den Blackrocktiefen diese 'Gürteltaschen'-Dinger tragen.",
    [4322] = "Helft Marshal Windsor, seine Ausrüstung zurückzuholen und seine Freunde zu befreien. Kehrt zu Marshal Windsor zurück, wenn Ihr Erfolg hattet.",
    [4324] = "Sprecht mit Yuka Screwspigot in der brennenden Steppe.",
    [4341] = "Begebt Euch in die Blackrocktiefen und findet Kharan Mighthammer.$B$BDer König erwähnte, dass Kharan dort gefangen sei - vielleicht solltet Ihr nach einem Gefängnis Ausschau halten.",
    [4342] = "Lasst Kharan Mighthammer seine Geschichte erzählen.",
    [4361] = "Kehrt nach Ironforge zurück und überbringt König Magni Bronzebeard die schlechten Nachrichten.",
    [4362] = "Kehrt in die Blackrocktiefen zurück und rettet Prinzessin Moira Bronzebeard aus den Fängen des bösen Imperators Dagran Thaurissan.",
    [4363] = "Kehrt nach Ironforge zurück und sprecht mit König Magni Bronzebeard.",
    [4487] = "Sprecht mit Strahad Farsan in Ratchet.",
    [4488] = "Sprecht mit Strahad Farsan in Ratchet.",
    [4489] = "Sprecht mit Strahad Farsan in Ratchet.",
    [4490] = "Sprecht in Ratchet mit Strahad Farsan, um zu lernen, wie man ein Teufelsross beschwört.",
    [4701] = "Begebt Euch zur Blackrockspitze und vernichtet die Quelle der Bedrohung durch die Worgs. Als Ihr Helendis verlasst, ruft er Euch noch einen Namen hinterher: Halycon. Darauf beziehen sich die Orcs im Zusammenhang mit den Worgs.",
    [4724] = "Erschlagt Halycon, die Rudelführerin der Worgs der Blutäxte.",
    [4729] = "Begebt Euch zur Blackrockspitze und sucht Worgwelpen der Blutäxte. Benutzt den Käfig, um die wilden kleinen Bestien zu transportieren. Bringt einen eingesperrten Worgwelpen zu Kibler.",
    [4734] = "Benutzt den Prototyp des Eiszilloskops an einem Ei im Horst.",
    [4735] = "Bringt 8 eingesammelte Dracheneier sowie das kollektronische Modul zu Tinkee Steamboil am Flammenkamm in der brennenden Steppe.",
    [4742] = "Sucht die drei Edelsteine der Befehlsgewalt: den Edelstein der Gluthauer, den Edelstein der Felsspitzoger und den Edelstein der Blutäxte. Bringt sie zusammen mit dem unverzierten Siegel des Aufstiegs zu Vaelan zurück.$B$BVaelan nannte Euch auch die Namen der drei Generäle: Kriegsmeister Voone von den Gluthauern, Hochlord Omokk von den Felsspitzogern und Oberanführer Wyrmthalak von den Blutäxten.",
    [4743] = "Reist zum Drachensumpf in den Marschen von Dustwallow. Sucht den alten Drachen Aschenschwinge auf und bekämpft ihn ohne Gnade, bis sein Wille gebrochen ist.$B$BIn genau diesem Moment müsst Ihr das ungeschmiedete Siegel des Aufstiegs vor der großen Bestie hinlegen. Dann müsst Ihr schnell die Kugel der drachischen Energie auf seine geschwächte Gestalt anwenden und die Kontrolle über seine geistigen Kräfte übernehmen. Kontrolliert die Bestie und zwingt die Flammen des schwarzen Drachenschwarms auf das ungeschmiedete Siegel des Aufstiegs!",
    [4764] = "Bringt Mayara Brightwing in der brennenden Steppe Doomriggers Schnalle.",
    [4765] = "Bringt Ridgewells Kiste zu Remington Ridgewell nach Stormwind.",
    [4766] = "Sprecht mit Mayara Brightwing in der brennenden Steppe.",
    [4768] = "Bringt der Schattenmagierin Vivian Lagrave in Kargath die Darkstone-Schrifttafel.",
    [4769] = "Sprecht mit Schattenmagierin Vivian Lagrave.",
    [4771] = "Legt die Dämmerungstrickfalle in den Vorführraum von Scholomance. Besiegt Vectus und kehrt dann zu Betina Bigglezink zurück.",
    [4787] = "Bringt das uralte Ei zu Yeh'kinya nach Tanaris.",
    [4788] = "Bringt Ausgrabungsleiter Ironboot in Tanaris die fünfte und sechste Schrifttafel von Mosh'aru.",
    [4862] = "Reist zur Blackrockspitze und sammelt 15 Spitzenspinnen-Eier für Kibler.$B$BLogischerweise müsstet Ihr diese Eier in der Nähe von Spinnen finden.",
    [4866] = "Ihr findet Mutter Glimmernetz im Herzen der Blackrockspitze. Kämpft mit ihr und bringt sie dazu, Euch zu vergiften. Es kann gut sein, dass Ihr sie sogar töten müsst. Kehrt zum struppigen John zurück, sobald Ihr vergiftet seid, damit er Euch 'melken' kann.",
    [4867] = "Lest Waroshs Rolle. Bringt Waroshs Mojo zu Warosh.",
    [4903] = "Tötet Hochlord Omokk, Kriegsmeister Voone und Oberanführer Wyrmthalak. Findet die wichtigen Blackrockdokumente. Kehrt zum Kriegsherrn Goretooth nach Kargath zurück, sobald Ihr diese Mission erledigt habt.",
    [4907] = "Sprecht mit Tinkee Steamboil.",
    [4921] = "Sucht Mankriks Frau und kehrt dann zu ihm nach Crossroads zurück.",
    [4941] = "Sprecht mit Etrigg in Orgrimmar. Wenn Ihr die Angelegenheit mit Etrigg besprochen habt, bittet Thrall um Rat.$B$BIhr erinnert Euch, dass Ihr Etrigg in Thralls Gemächern gesehen habt.",
    [4974] = "Begebt Euch zur Blackrockspitze und tötet den Kriegshäuptling Rend Blackhand. Nehmt seinen Kopf und kehrt nach Orgrimmar zurück.",
    [4981] = "Begebt Euch zur Blackrockspitze und findet heraus, was aus Bijou geworden ist.",
    [4982] = "Sucht Bijous Habseligkeiten und bringt sie ihr. Ihr erinnert Euch daran, dass sie erwähnte, ihre Sachen auf der untersten Ebene der Stadt versteckt zu haben.",
    [4983] = "Bringt Bijous Aufklärungsbericht zu Großmeister Lexlort nach Kargath.",
    [5001] = "Sucht Bijous Habseligkeiten und bringt sie ihr. Viel Glück!",
    [5002] = "Begebt Euch in die brennende Steppe und leitet Bijous Informationen an Marshal Maxwell weiter.",
    [5047] = "Sprecht mit Malyfous Darkhammer in Everlook.",
    [5061] = "Kehrt nach Darnassus zurück und zeigt Mathrengyl Bearwalker den Anhänger des Seelöwen.",
    [5065] = "Bringt Ausgrabungsleiter Ironboot in Tanaris die dritte und vierte Schrifttafel von Mosh'aru.",
    [5081] = "Reist zur Blackrockspitze und schaltet Kriegsmeister Voone, Hochlord Omokk und Oberanführer Wyrmthalak aus. Kehrt zu Marshal Maxwell zurück, wenn Eure Aufgabe erledigt ist.",
    [5089] = "Bringt den Befehl von General Drakkisath zu Marshal Maxwell in der brennenden Steppe.",
    [5096] = "Zieht zum Basislager des Scharlachroten Kreuzzugs zwischen dem Teufelssteinfeld und Dalsons Tränenfeld und zerstört sein Kommandozelt.$B$BLasst das Banner der Geißel im Lager wehen und kehrt dann zu Hochexekutor Derrington am Bollwerk in den Westlichen Pestländern zurück.",
    [5097] = "Markiert mit der Signalfackel jeden Turm in Andorhal; Ihr müsst im Eingang jedes Turmes stehen, um ihn erfolgreich zu markieren.$B$BWenn alle vier Türme markiert sind, bringt Ihr die Signalfackel zu Kommandant Ashlam Valorfist an der Chillwindspitze, Westliche Pestländer, zurück.",
    [5098] = "Markiert mit der Signalfackel jeden Turm in Andorhal; Ihr müsst im Eingang jedes Turmes stehen, um ihn erfolgreich zu markieren.$B$BWenn alle vier Türme markiert sind, bringt Ihr die Signalfackel zu Hochexekutor Derrington am Bollwerk, Westliche Pestländer, zurück.",
    [5102] = "Begebt Euch zur Blackrockspitze und schaltet General Drakkisath aus. Kehrt zu Marshal Maxwell zurück, wenn Eure Aufgabe erledigt ist.",
    [5122] = "Die Macht dieser Kapelle gibt mir die Kraft, der Verderbnis in meinem Herzen zu widerstehen. Wenn ich sie verlasse, werde ich zu einem Todesritter. Aber es gibt ein Medaillon, das Medaillon des Glaubens, das mir so viel Kraft geben wird, dass ich trotzdem gehen kann.$B$BBitte, $N, findet das Medaillon für mich. Es wird von Malor dem Eifrigen bewacht, einem wahnsinnigen Mitglied der Scharlachroten Bruderschaft. Er lebt tief in der scharlachroten Bastion im westlichen Stratholme.",
    [5125] = "$N, ich sterbe... aber meine Seele ist gerettet. Dafür schulde ich Euch mehr, als man mit Worten ausdrücken kann. Bitte, nehmt dies... und kämpft weiter so mutig, $C!",
    [5127] = "Begebt Euch zur Blackrockspitze und sucht Goraluk Hammerbruch. Erschlagt ihn und wendet dann die blutbefleckte Pike auf seine Leiche an. Nachdem seine Seele abgesaugt wurde, wird die Pike seelenbefleckt sein.$B$BIhr müsst außerdem die ungeschmiedete runenbedeckte Brustplatte finden.$B$BBringt die seelenbefleckte Pike und die ungeschmiedete runenbedeckte Brustplate zu Lorax in Winterspring.",
    [5142] = "Sucht Pamela Redpath.",
    [5149] = "Sucht Pamelas Puppe.",
    [5152] = "Sprecht mit Marlene, südlich der Ruinen von Andorhal.",
    [5153] = "Bringt Josephs Ehering zu Chromie.",
    [5154] = "Bringt die 'Annalen von Darrowshire' zu Chromie in Andorhal.",
    [5160] = "Begebt Euch nach Winterspring und sucht Haleh. Gebt ihr Awbees Schuppe.",
    [5163] = "Nehmt Umis mechanischen Yeti und erschreckt ihre Freunde damit:$B$BLegacki in Everlook (Winterspring)$BSprinkle in Gadgetzan (Tanaris)$BQuixxil in Marshals Zuflucht (Un'Goro Krater)$B$BWenn Ihr damit fertig seid, bringt den mechanischen Yeti zu Umi zurück.",
    [5168] = "Bringt Davils Buchband und Redpaths Schild zu Carlin Redpath.",
    [5181] = "Bringt den Schädel von Horgus und das zertrümmerte Schwert von Marduk zu Carlin Redpath in der Kapelle des hoffnungsvollen Lichts.",
    [5206] = "Bringt 5 widerhallende Schädel und den mystischen Kristall zu Carlin Redpath in den Östlichen Pestländern.",
    [5210] = "Bringt die erweiterten 'Annalen von Darrowshire' zu Carlin Redpath in den Östlichen Pestländern.",
    [5211] = "Befreit 15 Geister von Darrowshire und kehrt dann zu Carlin Redpath zurück.",
    [5212] = "Sammelt 20 verseuchte Fleischproben in Stratholme und bringt sie zu Betina Bigglezink zurück. Ihr vermutet, dass Ihr besagte Fleischproben bei jeder Kreatur in Stratholme finden könnt.",
    [5213] = "Reist nach Stratholme und durchsucht die Ziggurats. Sucht neue Geißeldaten und bringt sie zu Betina Bigglezink zurück.",
    [5214] = "Sucht Ezra Grimms Raucherladen in Stratholme und bergt einen Kasten von Grimms Tollem Tabak. Kehrt zu Smokey LaRue zurück, wenn Eure Aufgabe erledigt ist.",
    [5241] = "Sucht Carlin Redpath.",
    [5243] = "Begebt Euch nach Stratholme im Norden. Durchsucht die Vorratskisten, die über die Stadt verstreut sind, und holt 5 Einheiten Heiliges Wasser von Stratholme. Kehrt zu Leonid Barthalomew dem Geachteten zurück, wenn Ihr genug der gesegneten Flüssigkeit gesammelt habt.",
    [5251] = "Reist nach Stratholme und sucht Archivar Galford vom Scharlachroten Kreuzzug. Vernichtet ihn und verbrennt das Scharlachrote Archiv.",
    [5262] = "Bringt den Kopf von Balnazzar zu Fürst Nicholas Zverenhoff in den Östlichen Pestländern.",
    [5263] = "Zieht nach Stratholme und vernichtet Baron Rivendare. Nehmt seinen Kopf und kehrt zu Fürst Nicholas Zverenhoff zurück.",
    [5282] = "Wendet Egans Blaster auf die geisterhaften und spektralen Bürger von Stratholme an. Wenn die ruhelosen Geister ihre geisterhaften Hüllen sprengen, wendet den Blaster erneut an - dann sind sie endlich frei!$B$BBefreit 15 ruhelose Seelen und kehrt zu Egan zurück.",
    [5341] = "Begebt Euch zur Scholomance und holt das Familienvermögen der Barovs zurück. Dieses Vermögen besteht aus vier Besitzurkunden: Es sind die Besitzurkunde für Caer Darrow, die Besitzurkunde für Brill, die Besitzurkunde für Tarrens Mühle und die Besitzurkunde für Southshore. Kehrt zu Alexi Barov zurück, sobald die Aufgabe erledigt ist.",
    [5342] = "Begebt Euch zum Chillwind-Lager - Territorium der Allianz - und ermordet Weldon Barov. Nehmt seinen Kopf und kehrt zu Alexi Barov zurück.$B$BSeid gewarnt, Weldon wird wahrscheinlich gut von Abschaum der Allianz geschützt.",
    [5343] = "Begebt Euch zur Scholomance und holt das Familienvermögen der Barovs zurück. Dieses Vermögen besteht aus vier Besitzurkunden: Es sind die Besitzurkunde für Caer Darrow, die Besitzurkunde für Brill, die Besitzurkunde für Tarrens Mühle und die Besitzurkunde für Southshore. Kehrt zu Weldon Barov zurück, sobald die Aufgabe erledigt ist.",
    [5344] = "Begebt Euch zum Bollwerk - Territorium der Horde - und ermordet Alexi Barov. Nehmt seinen Kopf und kehrt zu Weldon Barov zurück.$B$BSeid gewarnt, Alexi wird wahrscheinlich gut durch Abschaum der Horde geschützt.",
    [5382] = "Sucht Doktor Theolen Krastinov in der Scholomance. Vernichtet ihn, verbrennt dann die Überreste von Eva Sarkhoff und die Überreste von Lucien Sarkhoff. Kehrt zu Eva Sarkhoff zurück, sobald Ihr die Aufgabe erfüllt habt.",
    [5383] = "Bringt die Tasche der Schrecken zu Eva Sarkhoff in Caer Darrow.",
    [5384] = "Kehrt mit dem Blut Unschuldiger zur Scholomance zurück. Sucht die Veranda und legt das Blut der Unschuldigen in die Kohlenpfanne. Kirtonos wird kommen, um sich von Eurer Seele zu nähren.$B$BKämpft tapfer, gebt keinen Fußbreit nach! Vernichtet Kirtonos und kehrt zu Eva Sarkhoff zurück.",
    [5461] = "Reist in das Arathihochland zu den Ruinen von Stromgarde. Durchsucht Stromgarde nach einem Andenken der Erinnerung. Wenn Ihr einen solchen Gegenstand findet, kehrt mit ihm zu Magistrat Marduke zurück.",
    [5462] = "Reist zur Hoffnung des Lichts in den Östlichen Pestländern und sucht Leonid Barthalomew den Geachteten auf. Zeigt ihm das Andenken der Erinnerung und berichtet ihm alles, was Ihr entdeckt habt.",
    [5463] = "Begebt Euch nach Stratholme und sucht Menethils Geschenk. Platziert das Andenken der Erinnerung auf dem unheiligen Boden.",
    [5464] = "Bringt das seelengebundene Andenken zu Leonid Barthalomew in den Östlichen Pestländern.",
    [5465] = "Kehrt zu Magistrat Marduke in Caer Darrow zurück. Zeigt ihm das seelengebundene Andenken.",
    [5466] = "Sucht Ras Frostraunen in der Scholomance. Wenn Ihr ihn gefunden habt, wendet das seelengebundene Andenken auf sein untotes Antlitz an. Solltet Ihr ihn erfolgreich in einen Sterblichen zurückverwandeln können, dann schlagt ihn nieder und nehmt den menschlichen Kopf von Ras Frostraunen an Euch. Bringt den Kopf zu Magistrat Marduke.",
    [5514] = "Bringt die magieerfüllten Skelettfragmente sowie 15 Goldstücke zu Krinkle Goodsteel in Gadgetzan.",
    [5515] = "Sucht nach Jandice Barov in der Scholomance und vernichtet sie. Entnehmt ihrer Leiche Krastinovs Tasche der Schrecken. Bringt die Tasche zu Eva Sarkhoff.",
    [5518] = "Bringt 4 Runenstoffballen, 8 Stücke unverwüstliches Leder, 2 Runenfaden und etwas Ogergerbemittel zu Knot Thimblejack. Momentan ist er im Gordokflügel von Düsterbruch angekettet.",
    [5525] = "Sie nennen ihn den Gordokfesselschlüssel - Naja, zumindest tun es diese \"Tonnenweise Spaß auf zwei Beinen\"-Oger. Ich denke einer der Oger müsste ihn haben, leider weiß ich nicht genau welcher. Möglicherweise ist die Chance größer, dass einer der Wachen ihn hat...$B$BWas erzähle ich da? - sicher habt Ihr ihn schon, oder? Ist es der da??!",
    [5528] = "Ihr jetzt de' Big Boss hier. Also kriegen freie Kostproben meiner besseren Gebräue! Diese Tränke werden Euch verstärken UND Euch Schädel weghauen! Das ist da' guta Zeug, Chef... Ihr versuchen und dann Kreeg glauben!",
    [5529] = "Tötet 20 verseuchte Jungtiere und kehrt dann zu Betina Bigglezink bei der Kapelle des hoffnungsvollen Lichts zurück.",
    [5531] = "Bringt die gefrorenen Eier zu Betina Bigglezink.",
    [5533] = "Sprecht mit Alchimist Arbington an der Chillwindspitze, Westliche Pestländer.",
    [5537] = "Bringt 15 Skelettfragmente zu Alchimist Arbington an der Chillwindspitze, Westliche Pestländer.",
    [5538] = "Bringt die magieerfüllten Skelettfragmente sowie 15 Goldstücke zu Krinkle Goodsteel in Gadgetzan.",
    [5582] = "Bringt die gesunde Großdrachenschuppe zu Betina Bigglezink bei der Kapelle des hoffnungsvollen Lichts in den Östlichen Pestländern.",
    [5601] = "Sucht Pamela Redpath in Darrowshire.",
    [5721] = "Legt das Reliktbündel auf den Marktplatz von Darrowshire.$B$BVerhindert Davil Lightfires Tod, bis Horgus stirbt.$B$BVerhindert Captain Redpaths Tod, bis Redpath der Verderbte erscheint.$B$BBesiegt Redpath den Verderbten.$B$BSprecht mit dem Geist von Josef Redpath, sobald er auf dem Marktplatz erscheint, und sprecht dann mit Pamela in ihrem Zuhause.",
    [5742] = "Hört Euch an, was Tirion Fordring zu sagen hat.",
    [5762] = "Bringt Kravels Kiste zu Hemet Nesingwary ins Schlingendorntal.",
    [5763] = "Bringt Roons Kodohorn zu Hemet Nesingwary ins Schlingendorntal.",
    [5781] = "Begebt Euch zum Tiefgewölbe im südlichsten Abschnitt der Östlichen Pestländer und sucht nach Taelans Hammer. Kehrt zu Tirion Fordring zurück, sobald Ihr Eure Mission abgeschlossen habt.",
    [5801] = "Bringt die Skelettschlüsselform und 2 Barren Thorium zur Spitze des Feuerfedergrats im Un'Goro Krater. Benutzt die Skelettschlüsselform am Lavasee, um den unvollendeten Skelettschlüssel zu schmieden.$B$BBringt den unvollendeten Skelettschlüssel dann zum Alchimisten Arbington an der Chillwindspitze in den Westlichen Pestländern.",
    [5802] = "Bringt die Skelettschlüsselform und 2 Barren Thorium zur Spitze des Feuerfedergrats im Un'Goro Krater. Benutzt die Skelettschlüsselform am Lavasee, um den unvollendeten Skelettschlüssel zu schmieden.$B$BBringt den unvollendeten Skelettschlüssel zu Apotheker Dithers im Bollwerk, Westliche Pestländer.",
    [5803] = "Zerstört Araj den Beschwörer und bringt Arajs Skarabäus zum Alchimisten Arbington an der Chillwindspitze in den westlichen Pestländern.",
    [5804] = "Vernichtet Araj den Beschwörer und bringt Arajs Skarabäus zum Apotheker Dithers im Bollwerk, in den westlichen Pestländern.",
    [5845] = "Reist nach Northdale im nordöstlichsten Gebiet der Östlichen Pestländer und sucht nach dem Symbol der verlorenen Ehre. Kehrt zu Tirion Fordring zurück, sobald Ihr Eure Mission abgeschlossen habt.",
    [5846] = "Begebt Euch zur Insel Caer Darrow im südlich-zentralen Bereich der Pestländer und sucht nach Hinweisen, wo sich das Gemälde befinden könnte.",
    [5848] = "Begebt Euch nach Stratholme im nördlichen Teil der Pestländer. In der scharlachroten Bastion findet Ihr das Gemälde 'Von Liebe und Familie', das zwischen anderen Gemälden versteckt ist und auf dem die Zwillingsmonde unserer Welt abgebildet sind.$B$BBringt das Gemälde zu Tirion Fordring.",
    [5861] = "Begebt Euch zu Uthers Grabmal in den Südlichen Pestländern. Zeigt Myranda der Vettel Tirions Geschenk.",
    [5862] = "Sprecht mit Myranda, um die scharlachrote Illusion zu erhalten. Begebt Euch nach Hearthglen, während Ihr unter dem Einfluss der scharlachroten Illusion steht, und übergebt dem Hochlord Taelan Fordring Tirions Geschenk.$B$BHearthglen liegt im Norden, Taelan dürfte sich in der Burg Mardenholde aufhalten.",
    [5921] = "Benutzt den Zauber 'Teleportation: Moonglade', um nach Moonglade zu reisen. Wenn Ihr dort ankommt, sprecht mit Dendrite Starblaze in Nighthaven.",
    [5922] = "Benutzt den Zauber 'Teleportation: Moonglade', um nach Moonglade zu reisen. Wenn Ihr dort ankommt, sprecht mit Dendrite Starblaze in Nighthaven.",
    [5923] = "Sprecht mit Mathrengyl Bearwalker in der Enklave von Cenarius in Darnassus.",
    [5924] = "Sprecht mit Mathrengyl Bearwalker in der Enklave von Cenarius in Darnassus.",
    [5925] = "Sprecht mit Mathrengyl Bearwalker in der Enklave von Cenarius in Darnassus.",
    [5926] = "Sprecht mit Turak Runetotem auf der Anhöhe der Ältesten in Thunder Bluff.",
    [5927] = "Sprecht mit Turak Runetotem auf der Anhöhe der Ältesten in Thunder Bluff.",
    [5928] = "Sprecht mit Turak Runetotem auf der Anhöhe der Ältesten in Thunder Bluff.",
    [5929] = "Sucht den großen Bärengeist im nordwestlichen Moonglade auf und lernt alles, was er Euch über die Natur des Bären mitzuteilen hat. Wenn Ihr das erledigt habt, kehrt zu Dendrite Starblaze nach Nighthaven in Moonglade zurück.",
    [5930] = "Sucht den großen Bärengeist im nordwestlichen Moonglade auf und lernt alles, was er Euch über die Natur des Bären mitzuteilen hat. Wenn Ihr das erledigt habt, kehrt zu Dendrite Starblaze nach Nighthaven in Moonglade zurück.",
    [5931] = "Kehrt nach Darnassus zurück und sprecht mit Mathrengyl Bearwalker in der Enklave von Cenarius.",
    [5932] = "Kehrt nach Thunder Bluff zurück und sprecht mit Turak Runetotem auf der Anhöhe der Ältesten.",
    [5941] = "Bringt das Reliktbündel zu Chromie nach Andorhal.",
    [5942] = "Bringt Josephs Schlüssel zu Josephs Truhe.",
    [5944] = "Geleitet Taelan Fordring aus Hearthglen hinaus.",
    [6001] = "Benutzt den Mondstaub des Cenarius mit dem Moonkinstein, um Mondklaue herauszulocken. Danach müsst Ihr Euch Mondklaue stellen und Euch die Kraft des Körpers und des Herzens verdienen, die er besitzt.$B$BSprecht mit Mathrengyl Bearwalker in Darnassus, wenn Ihr fertig seid.",
    [6002] = "Benutzt den Lunarstaub des Cenarius mit dem Moonkinstein, um Mondklaue herauszulocken. Danach müsst Ihr Euch Mondklaue stellen und Euch die Kraft des Körpers und des Herzens verdienen, die er besitzt.$B$BSprecht mit Turak Runetotem in Thunder Bluff, wenn Ihr fertig seid.",
    [6004] = "Tötet 2 scharlachrote Sanitäter, 2 scharlachrote Jäger, 2 scharlachrote Magi und 2 scharlachrote Ritter, bevor Ihr zu Kirsta Deepshadow in den Westlichen Pestländern zurückkehrt.",
    [6023] = "Besiegt Jägerin Radley und Chevalier Durgen, bevor Ihr zu Kirsta Deepshadow in den Westlichen Pestländern zurückkehrt.",
    [6025] = "Geht nach Hearthglen, sucht einen hohen Aussichtspunkt, von dem aus Ihr die Stadt überblicken könnt, schätzt die Streitkräfte des Scharlachroten Kreuzzugs und kehrt dann zu Kirsta Deepshadow in den Westlichen Pestländern zurück.",
    [6061] = "Benutzt die Zähmrute, um einen ausgewachsenen Ebenenschreiter zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Yaw Sharpmane in Bloodhoof.",
    [6062] = "Benutzt die Zähmrute, um einen scheckigen Terroreber zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Thotar in Klingenhügel.",
    [6063] = "Benutzt die Zähmrute, um einen Waldweberlauerer zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Dazalar in Dolanaar.",
    [6064] = "Benutzt die Zähmrute, um einen großen Klippeneber zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Grif Wildheart in Kharanos.",
    [6065] = "Sprecht mit Yaw Sharpmane in Bloodhoof.",
    [6066] = "Sprecht mit Yaw Sharpmane in Bloodhoof.",
    [6067] = "Sprecht mit Yaw Sharpmane in Bloodhoof.",
    [6068] = "Sprecht mit Thotar in Klingenhügel.",
    [6069] = "Sprecht mit Thotar in Klingenhügel.",
    [6070] = "Sprecht mit Thotar in Klingenhügel.",
    [6071] = "Sprecht mit Dazalar in Dolanaar.",
