    [97175] = "Reist nach Orgrimmar und holt Euch das Weihrauchfass des Exorzismus von Hohepriester Zayus. Ihr müsst eine Spende von 150 Gold leisten, um es zu erhalten.",
    [97176] = "Benutzt das Weihrauchfass des Exorzismus, um die gequälten Geister im Schreckenstal auszutreiben. Wenn Ihr 25 Geister des Schreckenstals vernichtet habt, kehrt zu Danitha Morr in der Bandarionfestung in Tirisfal zurück.",
    [97177] = "Bringt den Weihrauchschwenker zu Danitha Morr in der Bandarionfestung in Tirisfal.",
    [97178] = "Sprecht mit Ott im Dorf Tarrens Mühle im Vorgebirge von Hillsbrad.",
